import SwiftUI
#if canImport(UIKit)
import UIKit
#endif

/// A REAL server-rendered hole image, BAKED for the design snapshot — actual CourseView geometry from
/// `hole_render.render_hole` (PIL), source **gid31669 hole 4** (Par 5, 518.8 m, a dogleg). The OB has been
/// flood-filled to pure **black** so the map blends into the black watch face. This snapshot demonstrates a
/// **par-5 SECOND shot**: you are ~200 m from the tee with ~319 m left — unreachable — so the caddie plays
/// a 3-wood lay-up to ~100 m short. Overlay 720×1120 at ppm≈1.442; px are the real `prep_hole` route.
enum WatchHoleMapSample {
    static let imageSize = CGSize(width: 720, height: 1120)
    static let ppm: CGFloat = 1.4419                      // display px per metre
    static let youPx = CGPoint(x: 504, y: 702)           // 2nd shot lie — 200 m from tee (route @200m)
    static let apexPx = CGPoint(x: 556, y: 562)          // dogleg apex (303 m) — bows the caddie line
    static let layupPx = CGPoint(x: 506, y: 403)         // lay-up target (419 m ≈ 100 m short of the green)
    static let greenCtrlPx = CGPoint(x: 498, y: 375)     // control point for the lay-up→green dashed curve
    static let pinPx = CGPoint(x: 435, y: 279)           // green centre / pin (518.8 m)
    static let lastShotPx = CGPoint(x: 435, y: 981)      // where the tee shot started (for 距上一杆 sense)

    #if canImport(UIKit)
    static let image: UIImage? = Data(base64Encoded: jpegBase64).flatMap(UIImage.init(data:))
    #endif

    static let jpegBase64 = ""
}
